/**
 * The two looks of the map. Both are served from this app rather than from a
 * style host: the light one is MapTiler Basic and the dark one is its recoloured
 * twin, and neither is hosted anywhere we could link to. Tiles still come from
 * OpenFreeMap, which serves OpenStreetMap data with no API key — the reason we
 * left CARTO, which started stamping "API KEY REQUIRED" on unkeyed tiles.
 *
 * The files live in `public/map-styles/`, are generated by
 * `scripts/build-map-styles.mjs`, and carry their licence next to them.
 */
export const MAP_STYLE_LIGHT = "/map-styles/basic.json";
export const MAP_STYLE_DARK = "/map-styles/basic-dark.json";

export function styleForTheme(resolvedTheme: string): string {
  return resolvedTheme === "dark" ? MAP_STYLE_DARK : MAP_STYLE_LIGHT;
}
